    "m75bde8e3bba4": "背景画像",
    "ma0e8be24d19d": "背景画像を変更する",
    "mae0e4e3a0979": "クリックしてプロフィールを編集...",
    "m5ad78db20614": "まだプロフィールがありません",
    "m8b3540e2da8f": "プライベートメッセージを送信する",
