    mf33772291629: "アカウントはまだ確認されておらず、デフォルトは現在の状態にのみ保持されます。",
    m9e89e53e2865: "入力画像には実際の人物が含まれている場合があります。現在のモデルは実在の人物マテリアルを受け入れません。実際の人物が含まれていない画像に変更して、もう一度お試しください。",
    mff592c157e91: "生成されたビデオには機密コンテンツが含まれている可能性があり、コンテンツ セキュリティ システムによってブロックされています。プロンプトの単語を変更して再試行してください。",
    mc3e7ea201e84: "入力コンテンツには機密情報が含まれている可能性があり、コンテンツ セキュリティ システムによって傍受されています。プロンプトの単語を変更して再試行してください。",
    m837cd60b44a6: "プロンプト ワードには機密コンテンツが含まれている可能性があるため、コンテンツ セキュリティ システムによってブロックされています。プロンプトの単語を変更して再試行してください。",
    m16af09e1c8d3: "入力画像には機密コンテンツが含まれている可能性があります。画像を変更してもう一度お試しください。",
    m8005df5ea697: "入力ビデオには機密コンテンツが含まれている可能性があります。ビデオを変更してもう一度お試しください。",
    mff328011b804: "ネットワーク接続が異常です。タスクのステータスを確認中です。結果は後ほどご確認ください。",
    m47251f2c6902: "参照ビデオの継続時間と出力ビデオの継続時間の合計は 30 秒を超えることはできません。参照ビデオが提供されていない場合、最大出力は 30 秒です。",
    m67c79e7ff44f: "出力ビデオの長さは 30 秒を超えることはできません。参照ビデオが提供されていない場合、最大出力時間は 30 秒です。",
    m5ace786bd54e: "参照ビデオの長さが制限を超えています。現在のチャンネルは最大 {value1} 秒をサポートしています。参照ビデオをトリミングして再試行してください。",
    m1b9129a8d05c: "参照オーディオの継続時間が制限を超えています。現在のチャンネルは最大 {value1} 秒をサポートします。音声をカットして、もう一度お試しください。",
    mfc6a047147d5: "参照ビデオ解像度が高すぎます: 現在のチャネルでは、単一フレーム内のピクセル数が {value1} を超えないことが必要です。参照ビデオの解像度を圧縮して再試行してください。",
    m8c9f8eed1d02: "参照オーディオ形式は現在のチャンネルではサポートされていません。一般的な MP3 または WAV を使用して再試行してください。",
