    m5ad19be12451: "Sony F55 デジタル シネマ プロジェクター、4K CineAlta、オプションのグローバル シャッター モード。 4K RAW出力に対応。代表作：『スパイダーマン：ホームカミング』、『スーサイド・スクワッド』、Netflixシリーズ。",
    mba4419155de1: "ソニーの主力デジタル シネマ プロジェクター F65 には、オーバーサンプリングして 4K を出力する 8K センサーが搭載されており、驚くべき画質を実現します。代表作：『オブリビオン』『エリジウム』『アメイジング・スパイダーマン2』『ピクセル・ウォーズ』。",
    m6d2b2642b938: "Sony FS7 ドキュメンタリーカメラは、ドキュメンタリー/TV シリーズの主力製品であり、コストパフォーマンスの王様です。人間工学に基づいたショルダーデザイン。代表作：BBCドキュメンタリー、ディスカバリーチャンネル、多数のTVシリーズ。",
    mefa531a0d41b: "Sony FS7 II ドキュメンタリーカメラ、FS7 のアップグレードバージョン、電子可変 ND フィルター、改良された人間工学。代表作：プロフェッショナルドキュメンタリー、企業ビデオ、ニュースインタビュー。",
    m726b663e0ed9: "Sony FX6 フルフレーム コンパクト シネマ プロジェクター、フルフレーム コンパクト シネマ プロジェクター、デュアル ネイティブ ISO (800/12800)。代表作：ウェディングムービー、ドキュメンタリー、YouTubeプロフェッショナルコンテンツ。",
    m082447cec1a6: "Sony FX9 フルフレームフラッグシップムービーカメラ、フルフレームフラッグシップ、電子可変ND、高速ハイブリッドオートフォーカス。代表作：『マンダロリアン』（一部）、Netflixシリーズ、高級ドキュメンタリー。",
    md41506735784: "ソニーのベニス型デジタル シネマ プロジェクター、ハリウッドの主流モデル、デュアル ネイティブ ISO 500/2500、取り外し可能なセンサー モジュール。代表作：『ジョーカー』（一部）、『ヴェノム』、『ブラック・ウィドウ』、『シャン・チー』。",
